import{_ as i,o as a,c as s,aw as t}from"./chunks/framework.DLufY-ao.js";const h=JSON.parse('{"title":"Кэширование","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/js/critical-rendering-path/optimization/caching.md","filePath":"wiki/dev-commit/js/critical-rendering-path/optimization/caching.md"}'),e={name:"wiki/dev-commit/js/critical-rendering-path/optimization/caching.md"};function r(m,l,u,c,o,d){return a(),s("div",null,[...l[0]||(l[0]=[t('<h1 id="кэширование" tabindex="-1">Кэширование <a class="header-anchor" href="#кэширование" aria-label="Permalink to &quot;Кэширование&quot;">​</a></h1><h2 id="информация" tabindex="-1">Информация <a class="header-anchor" href="#информация" aria-label="Permalink to &quot;Информация&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li><strong>Кэширование (кэш)</strong> - это некий промежуточный буфер, в котором хранятся данные. Благодаря кэшированию страница сайта не воссоздается заново для каждого пользователя. Кэширование позволяет осуществлять работу с большим количеством данных в максимально сжатые сроки и при ограниченных ресурсах (серверных и пользовательских).</li></ul></div><h2 id="виды-кэширования" tabindex="-1">Виды кэширования <a class="header-anchor" href="#виды-кэширования" aria-label="Permalink to &quot;Виды кэширования&quot;">​</a></h2><h3 id="_1-браузерное-кэширование-клиентское-кэширование" tabindex="-1">1. Браузерное кэширование (клиентское кэширование) <a class="header-anchor" href="#_1-браузерное-кэширование-клиентское-кэширование" aria-label="Permalink to &quot;1. Браузерное кэширование (клиентское кэширование)&quot;">​</a></h3><ul><li>Представляет собой составление для браузера команды использовать имеющуюся кэшированную копию. Работа такого кэширования основана на том, что при повторном посещении, браузеру отдаётся заголовок 304 Not Modified, а сама страница или картинка загружаются из локального пользовательского кэша. Получается, что вы экономите на трафике между браузером посетителя и хостингом сайта. Соответственно, страница вашего сайта начинает загружаться быстрее.</li></ul><details class="details custom-block"><summary>Кэширование файлов и картинок</summary><ul><li>Картинка не скачивается каждый раз при открытии сайта, а просто загружается через кэш браузера.</li><li>Это первый уровень кэширования, который состоит в отдаче заголовка «expired» и заголовка «304 Not Modified». Наиболее эффективным считается кэширование на 2 недели.</li><li>Но если изображение на сайте меняется, то браузер узнает об этом не сразу, а только если выждать expiry или сбросить кэш в самом браузере. Это не очень эффективно, если файл постоянно изменяется и необходимо постоянно отдавать его актуальную версию.</li></ul></details><details class="details custom-block"><summary>Кэширование HTTPS</summary><ul><li>Специальные заголовки вида strict-security.</li><li>Позволяет браузеру всегда обращаться по https к выбранному домену. Сохраняет это состояние довольно жёстко и, в случае отмены этого вида кэша, браузер ещё довольно долго будет пытаться загрузить страницу по https, при этом игнорируя текущие заголовки.</li></ul></details><details class="details custom-block"><summary>Кэширование центра сертификации (Stamp центра сертификации)</summary><ul><li>Данный вид кэширования считается обязательным для применения, если вы не хотите, чтобы пользователи вашего сайта ждали, когда центр сертификации (а это некий сервер, который отвечает за достоверность вашего сертификата) обработает запрос от браузера пользователя и подтвердит, что ваш сайт действительно подтверждён им.</li></ul></details><details class="details custom-block"><summary>Кэширование страниц</summary><ul><li>Когда страница уже сгенерирована, нужно постоянно отслеживать ее актуальность. Для этого вы должны использовать серверный кэш с отслеживанием времени изменения отдельных частей страницы (если страница строится из множества динамически генерируемых блоков). При таком подходе в каждом ответе от сервера установлены специальные заголовки, обозначающие время изменения страницы, которые затем отправляются браузером пользователя при повторном обращении к странице сайта. Сервер при получении таких заголовков может проанализировать текущее состояние страницы (возможно, даже отрисовать её), но вместо содержимого страницы отдать заголовок «304 Not Modified», что для пользовательского браузера будет означать, что можно показать страницу из своего (браузера пользователя) кэша.</li><li>Конечно, можно отправлять соответствующие заголовки без использования серверного отслеживания кэша, но в таком случае большинство пользователей получат обновление контента страницы довольно поздно. При таком подходе браузер иногда опрашивает сервер для получения обновлений, но периодичность и правила для каждого браузера настраиваются его разработчиком, поэтому надеяться на то, что ваши пользователи получат обновления вовремя, не приходится.</li></ul><hr><p><strong>Как правило, кэш подразделяется по типу пользователей:</strong></p><ul><li>Для авторизованных</li><li>Для неавторизованных</li></ul><hr><ul><li>Данное разделение обусловлено уникальностью контента, для каждого авторизованного пользователя и общностью контента для гостевых пользователей. В большинстве сайтов не авторизованный пользователь не может изменять содержимое сайта, а значит и влиять на его содержимое.</li><li>Браузерный кэш позволяет экономить трафик и время, затрачиваемое на загрузку страниц. Но для достижения эффекта экономии, пользователь должен хотя бы один раз посетить нашу страницу, а это означает, что нагрузка на серверные ресурсы уменьшится, но не значительно.</li></ul></details><hr><h3 id="_2-серверное-кэширование" tabindex="-1">2. Серверное кэширование <a class="header-anchor" href="#_2-серверное-кэширование" aria-label="Permalink to &quot;2. Серверное кэширование&quot;">​</a></h3><ul><li>Под серверным кэшированием понимаются все виды кэширования, при котором данные хранятся на серверной стороне. Эти данные не доступны клиентским браузерам.</li><li>Кэш создаётся и хранится по принципу «один ко многим» (многие, в данном случае, — это клиентские устройства).</li></ul><details class="details custom-block"><summary>Кэширование страницы целиком</summary><ul><li>Наиболее эффективный кэш.</li><li>Отдача страницы происходит практически в момент обращения, как следствие – это возможность обработки миллионов запросов даже на самом слабом сервере со скоростью работы памяти и с незначительным задействованием процессора.</li><li><em>Минусы</em>: невозможность кэшировать страницы для авторизованного пользователя, либо пользователя, содержимое страницы которого зависит от текущих переменных пользователя.</li><li>Используйте этот кэш, если серверу известны все статичные состояния внешних данных, такие как: uri, get (без дополнительных параметров), пользователь не авторизован — т.е., фактически, это идеальное состояние страницы для гостевых пользователей. Учитывайте тот факт, что при таком кэшировании архитектура сайта или приложения всегда должна однотипно обрабатывать входящие запросы и отдавать однотипные ответы. Такое состояние есть в любом приложении или сайте, его нужно лишь отследить и применить к нему кэш.</li><li>Кэширование страниц целиком, чаще всего, применяют в каких-то экстренных случаях, при этом кэш страниц сохраняется на заранее указанное время (от 2 минут), в течение которого ответы от сервера однотипны (не позволяйте браузеру кэшировать это).</li></ul></details><details class="details custom-block"><summary>Кэширование результатов компиляции PHP-файлов</summary><p>Различают как чистую компиляцию кода, так и его оптимизацию во время компилирования (подмена скриптов):</p><ul><li>APC</li><li>XCache</li><li>Компиляция с подменой скриптов HipHopVirtualMachine</li></ul></details><details class="details custom-block"><summary>Кэширование отдельных блоков страницы</summary><ul><li>Сложный вид кэширования</li><li><em>Необходимо отслеживать</em>: состояние таблиц, состояние сессии пользователя, выключать ли кэширование при POST или GET запросах (http query), зависимость от текущего адреса, постоянство кэширования (при изменении предыдущих условий) или его динамическую подстройку.</li><li><em>Применение</em>: если нужно, уменьшить количество запросов к базе данных от реальных (авторизованных) пользователей</li></ul></details><details class="details custom-block"><summary>Кэширование PHP на основе неразделяемых ресурсов</summary><ul><li>Лучше всего подходит при стандартизации запросов, получении данных из общих ресурсов, наличии внутренних переменных, к которым php-ресурсы обращаются несколько раз при генерации страницы.</li></ul></details><details class="details custom-block"><summary>Кэширование PHP на основе общих ресурсов</summary><ul><li>Применяется для хранения сериализированных данных: конфигурационного файла, состояния таблиц, списков файловой системы.</li></ul></details><details class="details custom-block"><summary>Кэширование MySQL на основе Query Cache</summary><ul><li>Кэшировать эти запросы имеет смысл, если чтений из таблицы немного больше чем записи.</li></ul></details><details class="details custom-block"><summary>Кэширование MySQL результатов работы, агрегирующие таблицы</summary><ul><li>Существует правило: обновлений данных должно быть значительно меньше, чем чтения для их отдачи. Т.е. не имеет смысл агрегировать то, что изменится в тот же момент, при этом важна актуальность агрегированных данных.</li></ul></details>',20)])])}const p=i(e,[["render",r]]);export{h as __pageData,p as default};
